# Generates tests/fixtures/external/ezdxf-r2018-rich.dxf (ezdxf 1.4.2): python3 generate-ezdxf-rich.py && mv rich.dxf ezdxf-r2018-rich.dxf
import ezdxf, math
doc = ezdxf.new('R2018', setup=True)
doc.header['$INSUNITS'] = 4
doc.layers.add('KONTUR', color=3, linetype='CONTINUOUS', lineweight=50)
doc.layers.add('OSIE', color=1, linetype='CENTER', lineweight=25)
doc.layers.add('UKRYTA', color=5).off()
doc.layers.add('ZAMROZONA', color=2).freeze()
msp = doc.modelspace()
msp.add_line((0,0),(100,0), dxfattribs={'layer':'KONTUR'})
msp.add_line((100,0),(100,60), dxfattribs={'layer':'KONTUR'})
msp.add_lwpolyline([(100,60,0,0,0.5),(0,60,0,0,0),(0,0)], format='xyseb', close=False, dxfattribs={'layer':'KONTUR'})
msp.add_circle((50,30), 10, dxfattribs={'layer':'KONTUR'})
msp.add_arc((50,30), 25, 30, 150, dxfattribs={'layer':'OSIE'})
msp.add_ellipse((50,30), major_axis=(20,0), ratio=0.4, start_param=0, end_param=math.tau, dxfattribs={'layer':'OSIE'})
msp.add_ellipse((150,30), major_axis=(0,20), ratio=0.5, start_param=0, end_param=math.pi, dxfattribs={'layer':'OSIE'})
msp.add_spline(fit_points=[(150,0),(160,20),(175,15),(190,40)], dxfattribs={'layer':'KONTUR'})
p2 = msp.add_polyline2d([(200,0),(220,0),(220,20),(200,20)], close=True, dxfattribs={'layer':'KONTUR'})
msp.add_line((0,100),(10,100), dxfattribs={'layer':'UKRYTA'})
msp.add_line((0,110),(10,110), dxfattribs={'layer':'ZAMROZONA'})
msp.add_text('Opis', dxfattribs={'height':3,'insert':(5,5)})
msp.add_mtext('Wiele linii', dxfattribs={'insert':(5,15),'char_height':3})
blk = doc.blocks.new('ZAWOR', base_point=(1,1))
blk.add_line((1,1),(11,1)); blk.add_circle((6,1), 2); blk.add_arc((1,1), 5, 0, 90)
inner = doc.blocks.new('PARA')
inner.add_blockref('ZAWOR', (0,0)); inner.add_blockref('ZAWOR', (20,0), dxfattribs={'rotation':90})
msp.add_blockref('ZAWOR', (300,0), dxfattribs={'xscale':2,'yscale':2,'rotation':30,'layer':'OSIE'})
msp.add_blockref('ZAWOR', (350,0), dxfattribs={'xscale':-1,'yscale':1})
msp.add_blockref('PARA', (400,0))
hatch = msp.add_hatch(color=2); hatch.paths.add_polyline_path([(0,0),(20,0),(20,20),(0,20)], is_closed=True)
msp.add_linear_dim(base=(0,-10), p1=(0,0), p2=(100,0)).render()
msp.add_point((500,500))
doc.saveas('rich.dxf')
print('entities', len(msp))
